if let Some(first) = sets.first() {
    let slice = os_str_as_bytes(first)?;

    // A trailing backslash is unescaped if the total number of consecutive
    // trailing backslashes is odd. An even number means every backslash is
    // escaped by the preceding one.
    let trailing_backslashes = slice.iter().rev().take_while(|&&b| b == b'\\').count();
    if trailing_backslashes % 2 == 1 {
        show!(USimpleError::new(
            0,
            "warning: an unescaped backslash at end of string is not portable"
        ));
    }
}

